import{_ as t,c as o,o as n,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"内容详情聚合","description":"","frontmatter":{"title":"内容详情聚合","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#3.2","branch":"main","level":1,"order":3.2},"headers":[],"relativePath":"posts/projects/zfeed/03-content-rpc-service/02-content-detail-aggregation.md","filePath":"posts/projects/zfeed/03-content-rpc-service/02-content-detail-aggregation.md","lastUpdated":1779632679000}'),r={name:"posts/projects/zfeed/03-content-rpc-service/02-content-detail-aggregation.md"};function a(i,e,l,p,d,g){return n(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="内容详情聚合" tabindex="-1">内容详情聚合 <a class="header-anchor" href="#内容详情聚合" aria-label="Permalink to &quot;内容详情聚合&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/front.api" target="_blank" rel="noreferrer">app/front/doc/front.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/routes.go" target="_blank" rel="noreferrer">app/front/internal/handler/routes.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/user/uploadavatarhandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/user/uploadavatarhandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/contentuploadscredentialslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/contentuploadscredentialslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/querylikeinfologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/querylikeinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content_grpc.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content_grpc.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.mod" target="_blank" rel="noreferrer">go.mod</a></li></ul></details><p><code>GetContentDetail</code> 是 <code>content-rpc</code> 服务中的关键读路径。它负责编排多个下游 RPC 调用，组装完整的 <code>ContentDetail</code> 消息，其中包含核心内容元数据、作者信息、实时互动计数，以及当前查看者的个性化状态。</p><h2 id="编排逻辑" tabindex="-1">编排逻辑 <a class="header-anchor" href="#编排逻辑" aria-label="Permalink to &quot;编排逻辑&quot;">​</a></h2><p><code>ContentDetailLogic</code> 中的 <code>GetContentDetail</code> 实现遵循两阶段流水线：</p><ol><li>基础读取：同步查询本地 MySQL 数据库，获取核心内容记录及对应扩展记录（文章或视频）。</li><li>并发增强：使用 <code>errgroup.Group</code> 并行请求 <code>user-rpc</code>、<code>count-rpc</code> 和 <code>interaction-rpc</code>，填充外部字段。</li></ol><h3 id="执行流程图" tabindex="-1">执行流程图 <a class="header-anchor" href="#执行流程图" aria-label="Permalink to &quot;执行流程图&quot;">​</a></h3><p>下图把逻辑聚合步骤映射到代码库中的内部函数和 RPC 客户端。</p><p>标题：GetContentDetail 执行流水线</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L113-L134" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#113-134</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L136-L178" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#136-178</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L180-L212" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#180-212</a></p><h2 id="超时预算与优雅降级" tabindex="-1">超时预算与优雅降级 <a class="header-anchor" href="#超时预算与优雅降级" aria-label="Permalink to &quot;超时预算与优雅降级&quot;">​</a></h2><p>为保证高可用，并避免慢速下游服务耗尽 <code>content-rpc</code> 线程池，系统对每次调用设置了严格超时，并实现优雅降级。</p><table tabindex="0"><thead><tr><th>下游服务</th><th>超时常量</th><th>常量名</th><th>降级行为</th></tr></thead><tbody><tr><td><code>count-rpc</code></td><td>200ms</td><td><code>CountTimeout</code></td><td>回退到 <code>zfeed_content</code> 表中存储的计数</td></tr><tr><td><code>user-rpc</code></td><td>150ms</td><td><code>AuthorTimeout</code></td><td>回退为“用户”（默认用户）和空头像</td></tr><tr><td><code>interaction-rpc</code></td><td>150ms</td><td><code>StateTimeout</code></td><td>将 <code>is_liked</code>、<code>is_favorited</code>、<code>is_following</code> 设为 <code>false</code></td></tr></tbody></table><h3 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h3><p><code>enrichDetail</code> 函数会为 <code>errgroup</code> 的每个分支使用 <code>context.WithTimeout</code>。如果某次调用失败或超时，结果结构中的 <code>ok</code> 标记（例如 <code>authorResult.ok</code>）会被设为 <code>false</code>，后续的 “Apply” 函数会使用默认值或旧值。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L24-L28" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#24-28</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L71-L103" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#71-103</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L128-L131" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#128-131</a></p><h2 id="viewerstate-模式" tabindex="-1">ViewerState 模式 <a class="header-anchor" href="#viewerstate-模式" aria-label="Permalink to &quot;ViewerState 模式&quot;">​</a></h2><p><code>ViewerState</code> 表示 <code>viewer_id</code>（已登录用户）与正在查看的内容之间的关系。该状态会动态计算，并且不会缓存在内容服务中，以确保用户动作能立即反映在详情页状态上。</p><h3 id="状态解析逻辑" tabindex="-1">状态解析逻辑 <a class="header-anchor" href="#状态解析逻辑" aria-label="Permalink to &quot;状态解析逻辑&quot;">​</a></h3><p><code>queryViewerState</code> 函数会编排三种不同的互动检查：</p><ol><li>点赞状态：调用 <code>likeservice.QueryLikeInfo</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L318-L322" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#318-322</a></li><li>收藏状态：调用 <code>favoriteservice.QueryFavoriteInfo</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L343-L347" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#343-347</a></li><li>关注状态：调用 <code>followservice.CheckFollow</code>，检查查看者是否关注内容作者。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L368-L371" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#368-371</a></li></ol><p>标题：ViewerState 数据流</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L283-L311" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#283-311</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L157-L176" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#157-176</a></p><h2 id="数据一致性与-重复计数-防护" tabindex="-1">数据一致性与“重复计数”防护 <a class="header-anchor" href="#数据一致性与-重复计数-防护" aria-label="Permalink to &quot;数据一致性与“重复计数”防护&quot;">​</a></h2><p>内容服务在 <code>zfeed_content</code> 表中维护“基础计数”（通过异步事件更新），而 <code>count-rpc</code> 提供实时的“事实来源”。</p><p>聚合时，<code>applyCounts</code> 会优先使用 <code>count-rpc</code> 的结果。不过，为了避免 UI 抖动或出现“互动按钮已激活但计数为零”的不一致状态，系统逻辑会确保查看者自身状态不会覆盖来自计数服务的聚合计数。</p><h3 id="实体映射" tabindex="-1">实体映射 <a class="header-anchor" href="#实体映射" aria-label="Permalink to &quot;实体映射&quot;">​</a></h3><p>下表说明代码实体如何映射到数据库和 RPC 响应。</p><table tabindex="0"><thead><tr><th>逻辑字段</th><th>代码实体</th><th>来源位置</th></tr></thead><tbody><tr><td>基础记录</td><td><code>contentBaseRow</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L44-L52" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#44-52</a></td></tr><tr><td>文章扩展</td><td><code>contentArticleRow</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L54-L60" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#54-60</a></td></tr><tr><td>视频扩展</td><td><code>contentVideoRow</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L62-L69" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#62-69</a></td></tr><tr><td>聚合结果</td><td><code>content.ContentDetail</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L157-L176" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#157-176</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#L18-L34" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#18-34</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L214-L238" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#214-238</a></p>',30)])])}const f=t(r,[["render",a]]);export{h as __pageData,f as default};
